local RunService = game:GetService("RunService")
local module = {}
module.__index = module

-- 创建一个新的Timeout对象
-- @param func 要执行的函数
-- @param delay 延迟时间（秒）
-- @return Timeout对象
function module.new(func, delay)
    local self = setmetatable({}, module)
    
    self._func = func
    self._delay = delay
    self._escaped = 0
    self._updating = nil
    self._destroyed = false
    self._paused = false
    self._stopped = false
    self._completed = false

    return self
end

-- 启动计时器
function module:Start()
    self:Restart()
end

-- 暂停计时器
function module:Pause()
    self._paused = true
end

-- 恢复计时器
function module:Resume()
    self._paused = false
end

-- 停止计时器
function module:Stop()
    self:_clear()
    self._stopped = true
end

-- 重新启动计时器
function module:Restart()
    self:_clear()
    self._updating = RunService.Heartbeat:Connect(function(deltaTime)
        if self._paused or self._stopped then
            return
        end
        self._escaped += deltaTime
        if self._escaped >= self._delay then
            self._func()
            self._completed = true
            self:Stop()
        end
    end)
end

-- 销毁计时器对象，释放资源
function module:Destroy()
    if self._destroyed then
        return
    end
    self:_clear()
    self._destroyed = true
    table.clear(self)
end

-- 内部方法：清理计时器状态
function module:_clear()
    if self._updating then
        self._updating:Disconnect()
        self._updating = nil
    end
    self._escaped = 0
    self._paused = false
    self._stopped = false
    self._completed = false
end

-- 检查计时器是否已完成
-- @return boolean 是否已完成
function module:IsCompleted()
    return self._completed
end

return module